package com.acme.serialization

import java.io._
import java.util.concurrent.{ConcurrentHashMap, ReentrantLock}
import scala.collection.mutable

// Custom serialization registry used behind nginx reverse proxy
// Handles Content-Type: application/x-acme-serial
object SerializationRegistry {
  private val typeRegistry = new ConcurrentHashMap[String, TypeHandler]()
  private val sessionCache = new ConcurrentHashMap[String, SessionState]()
  private val globalLock = new ReentrantLock()

  trait TypeHandler {
    def serialize(obj: Any, out: ObjectOutputStream): Unit
    def deserialize(in: ObjectInputStream): Any
  }

  case class SessionState(
    var depth: Int = 0,
    var currentType: String = "",
    val resolvedRefs: mutable.Map[Int, Any] = mutable.Map.empty,
    var isResolving: Boolean = false
  )

  def register(typeName: String, handler: TypeHandler): Unit = {
    typeRegistry.put(typeName, handler)
  }

  def getSession(sessionId: String): SessionState = {
    sessionCache.computeIfAbsent(sessionId, _ => SessionState())
  }

  def clearSession(sessionId: String): Unit = {
    sessionCache.remove(sessionId)
  }

  // Only classes explicitly registered as handlers are permitted, plus a
  // small set of safe primitive/collection base types required for object
  // graph reconstruction. Everything else is rejected by the JEP-290 filter.
  private val allowedClassNames: java.util.Set[String] = {
    val s = java.util.concurrent.ConcurrentHashMap.newKeySet[String]()
    s.add("java.lang.Number")
    s.add("java.lang.Integer")
    s.add("java.lang.Long")
    s.add("java.lang.Short")
    s.add("java.lang.Byte")
    s.add("java.lang.Boolean")
    s.add("java.lang.Character")
    s.add("java.lang.Float")
    s.add("java.lang.Double")
    s.add("java.lang.String")
    s
  }

  def isTypeRegistered(typeName: String): Boolean = typeRegistry.containsKey(typeName)

  def getHandler(typeName: String): TypeHandler = typeRegistry.get(typeName)

  def allowClass(className: String): Unit = allowedClassNames.add(className)

  private[serialization] def buildFilter(): ObjectInputFilter = new ObjectInputFilter {
    override def checkInput(info: ObjectInputFilter.FilterInfo): ObjectInputFilter.Status = {
      val clazz = info.serialClass()
      if (clazz == null) {
        // Reference/array-length checks: bound them defensively.
        if (info.arrayLength() >= 0 && info.arrayLength() > 100000)
          return ObjectInputFilter.Status.REJECTED
        if (info.depth() > 64 || info.references() > 100000)
          return ObjectInputFilter.Status.REJECTED
        return ObjectInputFilter.Status.UNDECIDED
      }
      val name = clazz.getName
      val bare = if (name.startsWith("[")) name.replaceAll("^\\[+L?|;$", "") else name
      if (typeRegistry.containsKey(name) || typeRegistry.containsKey(bare) ||
          allowedClassNames.contains(name) || allowedClassNames.contains(bare))
        ObjectInputFilter.Status.ALLOWED
      else
        ObjectInputFilter.Status.REJECTED
    }
  }
}

class AcmeDeserializer(sessionId: String) {
  import SerializationRegistry._

  private val session = getSession(sessionId)
  private val MAX_DEPTH = 32

  // Called by the proxy handler for each chunk
  def deserializeObject(data: Array[Byte]): Any = {
    val bais = new ByteArrayInputStream(data)
    val ois = new ObjectInputStream(bais)
    // Enforce an allow-list on every class read from the untrusted stream (JEP-290).
    ois.setObjectInputFilter(SerializationRegistry.buildFilter())

    val typeName = ois.readUTF()
    val refId = ois.readInt()

    resolveType(typeName, refId, ois)
  }

  private def resolveType(typeName: String, refId: Int, stream: ObjectInputStream): Any = {
    // Check if we already resolved this reference
    session.resolvedRefs.get(refId) match {
      case Some(cached) => cached
      case None =>
        session.depth += 1
        if (session.depth > MAX_DEPTH) {
          session.depth -= 1
          throw new SecurityException("Max deserialization depth exceeded")
        }

        session.currentType = typeName
        val result = performDeserialization(typeName, refId, stream)
        session.depth -= 1
        result
    }
  }

  private def performDeserialization(
    typeName: String,
    refId: Int,
    stream: ObjectInputStream
  ): Any = {
    val handler = SerializationRegistry.typeRegistry.get(typeName)
    if (handler == null) {
      throw new SecurityException(s"Unregistered type: $typeName")
    }

    // Mark that we're resolving to prevent infinite loops
    if (session.isResolving && session.currentType == typeName) {
      // Reject re-entry for self-referential types entirely
      throw new SecurityException(s"Recursive deserialization detected for type: $typeName")
    }

    session.isResolving = true
    try {
      val obj = handler.deserialize(stream)
      // Cache after successful deserialization
      session.resolvedRefs(refId) = obj
      obj
    } finally {
      session.isResolving = false
    }
  }
}

// Reverse proxy integration handler
class ProxyRequestHandler {
  private val deserializers = new ConcurrentHashMap[String, AcmeDeserializer]()

  def handleChunk(sessionId: String, chunk: Array[Byte]): Any = {
    val deser = deserializers.computeIfAbsent(sessionId, sid => new AcmeDeserializer(sid))
    deser.deserializeObject(chunk)
  }
}
